"""Private three-way comparison and public candidate-only review."""
from pathlib import Path
from PIL import Image
import json, shutil, html
R=Path(__file__).resolve().parents[1];W=R/'work/left-engine-r13';P=R/'public/review';P.mkdir(exist_ok=True)
e=json.loads((R/'public/assets/mechanics/left-vr-r01/evidence.json').read_text());fit=json.loads((W/'grid-fit.json').read_text());contours=json.loads((W/'review/grid/contours.json').read_text());capture=json.loads((W/'review/candidate/report.json').read_text());author=json.loads((R/'public/assets/mechanics/left-vr-r01/authoring.json').read_text());folder=P/'left-engine-grid-r13';folder.mkdir(exist_ok=True)
assert len(capture['views'])==len(e['poses'])and not capture['errors']
assert capture['assets']=={name:info['sha256']for name,info in author['runtime']['files'].items()},'Capture/export asset binding differs'
assert all(not v['stats']['errors']and v['exposure']==.05 and v['position']==e['camera']['sourcePosition']for v in capture['views'])
browser=json.loads((W/'browser.json').read_text());perf=json.loads((W/'performance.json').read_text());baseline_perf=json.loads((W/'performance-r11.json').read_text());default=json.loads((W/'review/default/comparison.json').read_text())
assert browser['pass']and perf['pass']and baseline_perf['pass']and default['pass']
assert browser['assets']==capture['assets'],'Functional checks must use the captured export'
for pose in e['poses']:
 for name in ['candidate','r11','r12']:
  im=Image.open(W/'review'/name/(pose['id']+'.png'));im.save(folder/(name+'-'+pose['id']+'.webp'),quality=90)
assessment=json.loads((W/'visual-assessment.json').read_text());assert assessment['masterSHA256']==author['masterSHA256']
report={'visualAssessment':assessment,'stage':'Grid-fit candidate, not a completed VR replica','camera':e['camera'],'fit':fit,'contours':contours,'capture':capture,'functional':browser,'performance':{'r11':baseline_perf,'candidate':perf},'defaultAppearance':default,'geometry':author['runtime']['lods'],'limits':['Casing and accessory shapes, fabric folds and finish remain under visual review.','Outline agreement from one panorama station does not establish real hull dimensions or hidden geometry.','SwiftShader checks establish correctness; they are not desktop/mobile hardware FPS results.']}
(folder/'validation.json').write_text(json.dumps(report,indent=2)+'\n')
style='body{font:16px/1.55 system-ui;margin:24px auto;max-width:1500px;padding:0 20px;background:#10161b;color:#e5e9ec}a{color:#77d6ff}h1,h2{line-height:1.2}.views{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.private{grid-template-columns:repeat(3,minmax(0,1fr))}figure{margin:0}img{width:100%;height:auto}figcaption{color:#bfcbd2}section{margin:36px 0}table{border-collapse:collapse}td,th{padding:6px 14px;border-bottom:1px solid #455}small{color:#c0c9ce}@media(max-width:850px){.views,.private{grid-template-columns:1fr}}'
intro='<h1>Motor izquierdo · carcasas y fundas · candidata R13</h1><p>Reconstrucción de carcasas, tapas, conexiones y pliegues mediante cuadros de 64/32 píxeles. Incluye materiales y reflejos recalculados. La candidata conserva diferencias documentadas con la VR y aún no acredita una réplica terminada.</p><p><a href="../?room=machinery&amp;engine=left-vr-grid-r13">Abrir candidata</a> · <a href="https://vrcloud.com/?pv=1667308298">Referencia VR</a> · <a href="./machinery.html">Versión R11</a></p>'
summary=f'<p>Una sola cámara estimada: {e["camera"]["sourcePosition"]}. Las ocho orientaciones comparten esa posición. Los {len(fit["controls"])} controles se miden sobre piezas reales del archivo Blender; error máximo {fit["maxErrorPixels"]:.1f} px de 2048. Son controles de ajuste, no mediciones independientes de la instalación real.</p>'
summary+='<table><tr><th>Contorno</th><th>Máximo en controles</th><th>Máximo fuera del ajuste</th></tr>'
for c in contours['contours']:summary+=f'<tr><td>{html.escape(c["group"])}</td><td>{c["maxErrorPixels"]:.1f} px</td><td>{c["heldOut"]["maxErrorPixels"]:.1f} px</td></tr>'
summary+='</table><p>Los bordes reservados se anotaron manualmente y no intervienen en la deformación. El encaje sigue los rayos de la panorámica; la profundidad oculta continúa inferida.</p>'
summary+='<p><a href="../assets/mechanics/left-vr-r01/component-inventory.json">Inventario por pieza: ubicación, material, fuente y clasificación</a></p><h2>Comprobaciones del visor</h2><p>Se verifican carga fallida y reintento, sustitución conjunta, detalle bajo demanda, corte nominal por lado, reproducción, filtros y reinicio. Tres recorridos de cambio de sala mantienen estables los recursos residentes.</p>'
delta=(browser['detail']['estimatedMemory']['totalBytes']-browser['baseline']['estimatedMemory']['totalBytes'])/1048576
summary+=f'<p>Conjunto izquierdo: {author["runtime"]["lods"]["walk"]["triangles"]:,} triángulos en recorrido y {author["runtime"]["lods"]["detail"]["triangles"]:,} en detalle. Incremento estimado máximo comprobado: {delta:.1f} MiB. La estimación excluye lienzo/MSAA, cachés del controlador y programas.</p>'
summary+='<p>Medición por software, Chromium/SwiftShader, 600 × 400, DPR del dispositivo 2; muestras cortas de 12 cuadros por secuencia, sin validación sostenida de rendimiento. CPU: '+html.escape(perf['environment']['cpu'])+'. Cuota de CPU: '+html.escape(perf['environment']['cpuQuota'])+'. Los percentiles siguientes no acreditan las metas de FPS en GPU física.</p><table><tr><th>Secuencia</th><th>R11 p50 / p95</th><th>Candidata p50 / p95</th><th>Resolución final</th><th>Dibujos / triángulos</th></tr>'
for a,b in zip(baseline_perf['sequences'],perf['sequences']):
 summary+=f'<tr><td>{html.escape(b["name"])}</td><td>{a["frameMs"]["p50"]:.1f} / {a["frameMs"]["p95"]:.1f} ms</td><td>{b["frameMs"]["p50"]:.1f} / {b["frameMs"]["p95"]:.1f} ms</td><td>{b["canvas"][0]} × {b["canvas"][1]}</td><td>{b["calls"]} / {b["triangles"]:,}</td></tr>'
summary+='</table><p>La referencia R11 conserva su medición anterior en este mismo entorno; R13 se mide de nuevo. Las mallas exteriores se preparan antes de cronometrar. Las secuencias recorren el pasillo de ida y vuelta mediante los controles de caminata; se miden por separado resolución fija, adaptable y corte animado. El informe JSON incluye muestras, descargas y estado de reposo. La vista predeterminada sin el parámetro de candidata no solicita los activos nuevos. La separación de piezas conserva todos los atributos y cambia 304 píxeles de borde de 540.000 (0,056 %); con el GLB original, el código nuevo reproduce R11 píxel por píxel. El informe conserva ambas comprobaciones.</p><p><a href="https://github.com/ageofresearch/ageofresearch.github.io/releases/tag/luz-left-engine-grid-r13">Escena Blender editable y fuentes</a> · <a href="left-engine-grid-r13/authoring-archive.json">Hashes del archivo de autoría</a></p>'
summary+='<h2>Diferencias observadas que impiden aprobar la réplica</h2><ul><li>Carcasa de admisión: rebordes, nervaduras, conexiones y malla todavía distintos.</li><li>Fundas: pliegues demasiado regulares; correas y cierres demasiado finos y angulosos.</li><li>Acabados: reflejos de metal excesivamente contrastados y variación residual en pintura.</li><li>Reductora y extintor: varias formas y uniones continúan simplificadas.</li></ul><p>Se corrigieron el barrido abierto del codo y la intersección de la funda plateada con el puño. El resto de diferencias se mantiene explícitamente pendiente.</p>'
public=intro+summary;private=intro+summary+'<h2>Superposición de contornos</h2><p>Cian: escape 3D. Magenta: funda 3D. Amarillo: controles de contorno, con distancia en píxeles. Referencia privada.</p><img src="grid/contours.png" alt="Contornos del modelo sobre la referencia original">'
for pose in e['poses']:
 id=pose['id'];title=f'{id} · H {pose["h"]}° / V {pose["v"]}° · HFOV {pose["hfov"]}° / VFOV {pose["vfov"]:.3f}°'
 public+=f'<section><h2>{title}</h2><div class="views"><figure><img src="left-engine-grid-r13/r11-{id}.webp"><figcaption>R11</figcaption></figure><figure><img src="left-engine-grid-r13/r12-{id}.webp"><figcaption>R12 anterior</figcaption></figure><figure><img src="left-engine-grid-r13/candidate-{id}.webp"><figcaption>Candidata R13 · salida real WebGL</figcaption></figure></div></section>'
 private+=f'<section><h2>{title}</h2><div class="views private">'+''.join(f'<figure><img src="{src}"><figcaption>{label}</figcaption></figure>'for src,label in [(f'../reference/{id}.png','VR original, remuestreo rectilíneo'),(f'r12/{id}.png','R12 anterior'),(f'candidate/{id}.png','Candidata R13, WebGL')])+'</div></section>'
tiles=json.loads((W/'review/tiles/inventory.json').read_text());summary_tiles=f'<h2>Revisión por cuadros</h2><p>{tiles["tileCount"]} celdas de 64/32 píxeles, agrupadas en {tiles["parent64Count"]} cuadros principales. Inventario y comparación privada con la VR original. La cobertura del inventario no equivale a aprobación visual.</p><p><a href="../assets/mechanics/left-vr-r01/tile-validation.json">Resultados de correspondencia por borde</a></p>';summary_tiles+='<p>Las métricas automáticas de apariencia cubren '+str(tiles['automaticallyAssessedCount'])+' celdas. Ninguna se aprueba automáticamente: faltan la comprobación manual de todas sus piezas interiores y la aceptación del acabado.</p><table><tr><th>Borde reservado (no usado para ajustar)</th><th>p95, píxeles originales</th><th>Objetivo ≤6 px</th></tr>'
for edge in tiles['heldOutEdges']:
 summary_tiles+=f'<tr><td>{html.escape(edge["name"])}</td><td>{edge["p95Pixels"]:.2f}</td><td>{"Cumple este borde" if edge["passed"] else "Pendiente"}</td></tr>'
summary_tiles+='</table><p>Estos bordes parciales no certifican el 95 % de todos los bordes del conjunto. Los controles generales tampoco cumplen todavía el máximo estricto de 4 píxeles. La promoción a versión predeterminada permanece bloqueada.</p>'
public+=summary_tiles;private+=summary_tiles+'<p><a href="tiles/index.html">Abrir comparación privada por cuadro</a></p>'
limits='<h2>Pendiente de calidad</h2><p>Formas de carcasas y accesorios, juntas, pliegues y costuras finas, rótulos y lectura de los reflejos. Se reconstruyeron las tapas visibles, la carcasa de admisión, los pliegues y conexiones próximas. Los errores residuales y las celdas pendientes siguen documentados; la candidata no ha superado todavía todos los criterios estrictos de correspondencia. El encaje de los contornos no resuelve esos detalles. La geometría derecha y los activos de inspección nominal se conservan.</p><p>La inspección izquierda cambia expresamente a la mecánica nominal R03. Al cerrar el corte restaura el exterior VR y retira su sombra reversible.</p><p><a href="left-engine-grid-r13/validation.json">Datos y capturas de validación</a>. Las fotografías VR permanecen privadas y no forman parte de las texturas publicadas.</p>'
private=(private+limits).replace('href="../?room=', 'href="https://ageofresearch.github.io/luz-de-mar-realism/?room=').replace('href="../assets/', 'href="https://ageofresearch.github.io/luz-de-mar-realism/assets/').replace('href="./machinery.html"', 'href="https://ageofresearch.github.io/luz-de-mar-realism/review/machinery.html"').replace('href="left-engine-grid-r13/', 'href="https://ageofresearch.github.io/luz-de-mar-realism/review/left-engine-grid-r13/')
for file,body in [(P/'left-engine-grid.html',public+limits),(W/'review/index.html',private)]:file.write_text('<!doctype html><html lang="es"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Motor izquierdo · detalle R13</title><style>'+style+'</style>'+body+'</html>')
print('Private and public grid comparison reports written')
